import{_ as s,o as t,c as i,a2 as n}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Handover preview","description":"","frontmatter":{},"headers":[],"relativePath":"handover-preview.md","filePath":"handover-preview.md","lastUpdated":1794043946000}'),a={name:"handover-preview.md"};function o(r,e,d,h,p,l){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="handover-preview" tabindex="-1">Handover preview <a class="header-anchor" href="#handover-preview" aria-label="Permalink to &quot;Handover preview&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Availability</p><p>This page describes the history and preview foundation in product PR <a href="https://github.com/open-agenthub/open-agenthub/pull/487" target="_blank" rel="noreferrer">#487</a>, tracked in <a href="https://github.com/open-agenthub/open-agenthub/issues/466" target="_blank" rel="noreferrer">#466</a>. It is not available in 1.18.0. Publish this guide with the release containing that change.</p></div><p>A handover preview lets a session owner prepare the exact text they would give another provider: instructions, current task, decisions, pending work and source references. The preview sends no conversation to a provider, starts no agent and changes no credentials. This step provides an API preview; there is no provider-switch button in Workspace yet.</p><p>The preview is a <strong>Community</strong> feature for the <strong>owner</strong> of an interactive session using the Terminal interface. Shared Collaborators, Viewers, peer agents and parent sessions cannot request it on someone else&#39;s behalf. Enterprise sharing continues to control who can read the conversation and does not grant handover authority.</p><h2 id="prepare-a-preview" tabindex="-1">Prepare a preview <a class="header-anchor" href="#prepare-a-preview" aria-label="Permalink to &quot;Prepare a preview&quot;">​</a></h2><p>Send an authenticated web API request to <code>POST /api/sessions/{id}/handover-preview</code>, using the same owner identity as your normal web API requests. This is not a personal-token <code>/remote</code> endpoint or an in-session MCP tool. Replace <code>session-id</code> with your session ID; <code>ACCESS_TOKEN</code> below is an access token for your installation&#39;s web API.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://hub.example.com/api/sessions/session-id/handover-preview</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ACCESS_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;target&quot;: &quot;Codex&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;instructions&quot;: &quot;Keep the current task scope and check changes before committing.&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;task&quot;: &quot;Finish the settings page.&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;decisions&quot;: &quot;Use the existing settings components.&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;pendingWork&quot;: &quot;Verify saving and reopening the page.&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;references&quot;: [&quot;frontend/src/settings.vue:12&quot;, &quot;https://example.com/spec&quot;]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p><code>target</code> accepts <code>Claude</code> or <code>Codex</code>. <code>instructions</code> and <code>task</code> are required. <code>decisions</code>, <code>pendingWork</code> and up to 32 <code>references</code> are optional. Review the returned <code>text</code>: it contains the complete framed selection, including the omission note.</p><p>The complete preview must fit <strong>16,000 characters</strong>, including headings and the omission note. An oversized selection is rejected with HTTP 400; shorten it yourself. Instructions and references are never silently truncated. Terminal control characters are rejected. The fixed opening keeps a leading slash in selected text from becoming a CLI command.</p><p>References are retained as text. The preview does not open referenced files or URLs, check that they exist, or attach their contents. Include needed details in your selection. Do not select credentials or other material you would not want to send to a target provider.</p><h2 id="what-is-omitted" tabindex="-1">What is omitted <a class="header-anchor" href="#what-is-omitted" aria-label="Permalink to &quot;What is omitted&quot;">​</a></h2><p>The explicit note lists earlier native messages, raw tool outputs, attachments, hidden reasoning and native resume files. Only your selected plain text is part of the preview. Historical coverage is reported as unknown; the preview does not pretend that the selection contains every instruction from the old conversation.</p><p><code>capacity</code> is <code>unknown</code>: a character count does not establish whether the target model has enough context space. <code>switchingAvailable</code> is <code>false</code>, with a reason explaining that runtime switching is not enabled and the workspace is ephemeral. There is no delivery acknowledgement, pod replacement, target sign-in or automatic continuation. Autonomous, scheduled and streaming chat sessions are refused. A missing or inaccessible session returns 404.</p><h2 id="conversation-history" tabindex="-1">Conversation history <a class="header-anchor" href="#conversation-history" aria-label="Permalink to &quot;Conversation history&quot;">​</a></h2><p>The history foundation keeps execution segments in one session conversation. When later runtime switching is enabled, a provider boundary will distinguish the segments; prior text will stay history rather than automatically becoming the next provider&#39;s model context. Existing sessions keep their native history and context-clear boundaries.</p><p>Existing single-execution sessions retain their current native full-history paging without a new total limit. Only a combined view containing several executions is bounded to 5,000 entries and approximately one million characters; an explicit omission boundary appears when earlier retained entries fall outside that view. Individual provider projections have their own retention and field limits. A missing or previously truncated native record cannot be reconstructed. History does not translate native resume files between providers. Sharing links and roles continue to apply to the same session.</p><p>See <a href="/docs/workspace">Workspace</a>, <a href="/docs/provider-login">Provider login</a> and <a href="/docs/questions-approvals">Questions and approvals</a> for the existing session controls.</p>`,17)])])}const g=s(a,[["render",o]]);export{u as __pageData,g as default};
